function select(i,initial=false){if(i<0||i>7)return;selected=i;[...$('track').children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-pressed',i===j)});[...$('planets').children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-current',i===j?'true':'false')});$('previous').disabled=i===0;$('next').disabled=i===7;align();clearTimeout(changeTimer);if(initial||reduced)details();else{document.querySelector('.information').classList.add('changing');changeTimer=setTimeout(details,190)}}
$('previous').onclick=()=>select(selected-1);$('next').onclick=()=>select(selected+1);document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea'))return;if(e.key==='ArrowLeft'){e.preventDefault();select(selected-1)}if(e.key==='ArrowRight'){e.preventDefault();select(selected+1)}});let touchX;document.querySelector('.gallery').addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});document.querySelector('.gallery').addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-touchX;if(Math.abs(dx)>45)select(selected+(dx<0?1:-1))},{passive:true});$('pause').textContent=paused?'Resume rotation':'Pause rotation';$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume rotation':'Pause rotation'};select(2,true);
setInterval(()=>{if(!paused&&!document.hidden){rotation+=.0003;paint(selected,rotation)}},160);
