 // Layered clouds and dust create depth without distracting from the planets.
 for(let i=0;i<85;i++){let x=w*(.05+rand()*.95),y=h*(.1+rand()*.8);const band=h*(.2+.42*x/w);y=band+(rand()-.5)*h*.35;const r=60+rand()*w*.16;const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,i%3?'rgba(81,69,155,.032)':'rgba(31,112,153,.035)');g.addColorStop(1,'rgba(10,12,30,0)');ctx.fillStyle=g;ctx.fillRect(x-r,y-r,r*2,r*2)}
