 for(let i=0;i<1150;i++){const x=rand()*w,y=rand()*h,r=rand(),a=.16+rand()*.64;ctx.fillStyle=i%7===0?`rgba(195,212,255,${a})`:`rgba(222,228,239,${a})`;ctx.beginPath();ctx.arc(x,y,.22+r*r*.95,0,7);ctx.fill();if(r>.982){let glow=ctx.createRadialGradient(x,y,0,x,y,7);glow.addColorStop(0,'#d9e9ff88');glow.addColorStop(1,'#b6d9ff00');ctx.fillStyle=glow;ctx.fillRect(x-7,y-7,14,14);ctx.strokeStyle='#d9e9ff55';ctx.lineWidth=.5;ctx.beginPath();ctx.moveTo(x-4,y);ctx.lineTo(x+4,y);ctx.moveTo(x,y-4);ctx.lineTo(x,y+4);ctx.stroke()}}
