$('music').onclick=async()=>{if(audioBusy)return;audioBusy=true;try{if(!audioCtx)createAmbience();await audioCtx.resume();musicOn=!musicOn;master.gain.cancelScheduledValues(audioCtx.currentTime);master.gain.setTargetAtTime(musicOn?Number($('volume').value)/100*.65:0,audioCtx.currentTime,.65);$('music').setAttribute('aria-pressed',String(musicOn));$('music').querySelector('b').textContent=musicOn?'ON':'OFF';$('music').title=musicOn?'Pause ambient space music':'Play ambient space music';$('audio-status').textContent=musicOn?'Ambient space music playing':'Ambient space music paused'}catch(error){$('audio-status').textContent='Audio could not start. Please try again.'}finally{audioBusy=false}};
